#!/usr/bin/env bash
# Runs the generated bash completion (reminders.bash in the current directory) for
# `reminders show <prefix>` and prints the candidates bash offers, one per line.
# Needs bash 4 or later, like the generated script. No `set -eu`: the generated functions
# aren't written for it.

prefix="$1"
# shellcheck disable=SC1091 # generated by check-completion.sh
source ./reminders.bash
# shellcheck disable=SC2034 # read by _reminders
COMP_WORDS=(reminders show "$prefix")
# shellcheck disable=SC2034
COMP_CWORD=2
COMP_LINE="reminders show $prefix"
# shellcheck disable=SC2034
COMP_POINT=${#COMP_LINE}
COMPREPLY=()
# The arguments bash passes to a completion function: command, current word, previous word.
_reminders reminders "$prefix" show
printf '%s\n' "${COMPREPLY[@]}"
